/* @lc app=leetcode id=3605 lang=kotlin */ class Solution { fun g(a: Int, b: Int): Int = if (b == 0) a else g(b, a % b) fun minStable(nums: IntArray, maxC: Int): Int = nums.size.let { n -> generateSequence(nums to 0) { (arr, k) -> (1 shl (k + 1)).takeIf { it <= n }?.let { len -> IntArray(n - len + 1) { i -> g(arr[i], arr[i + (1 shl k)]) } to k + 1 } }.map { it.first }.toList().let { sp -> generateSequence(0 to n) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { L -> if (generateSequence(0 to 0) { (i, ops) -> if (i + L > n - 1) null else (31 - Integer.numberOfLeadingZeros(L + 1)).let { kk -> if (g(sp[kk][i], sp[kk][i + L - (1 shl kk) + 1]) > 1) (i + L + 1) to ops + 1 else (i + 1) to ops } }.last().second <= maxC) lo to L else L + 1 to hi } }.last().first } } }